import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.http.*
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class TokenBucket(
    var tokens: Int,
    var lastRefillTime: Long,
    val capacity: Int = 100,
    val refillRatePerMs: Int = 1
)

val buckets = ConcurrentHashMap<String, TokenBucket>()
val API_SECRET = System.getenv("API_SECRET") ?: "default-secret-change-in-prod"

fun verifyHmacSignature(payload: String, signature: String, secret: String): Boolean {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
    val expected = Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(payload.toByteArray()))
    // Constant-time comparison
    if (expected.length != signature.length) return false
    var result = 0
    for (i in expected.indices) {
        result = result or (expected[i].code xor signature[i].code)
    }
    return result == 0
}

fun getClientIdentifier(call: ApplicationCall): String? {
    val authHeader = call.request.headers["Authorization"] ?: return null
    if (!authHeader.startsWith("HMAC ")) return null
    val parts = authHeader.removePrefix("HMAC ").split(":")
    if (parts.size != 3) return null
    val (clientId, timestamp, signature) = parts

    // Verify timestamp freshness (5 minute window)
    val ts = timestamp.toLongOrNull() ?: return null
    val now = System.currentTimeMillis()
    if (Math.abs(now - ts) > 300_000) return null

    // Verify signature
    val payload = "$clientId:$timestamp"
    if (!verifyHmacSignature(payload, signature, API_SECRET)) return null

    return clientId
}

/**
 * Refills tokens based on elapsed time since last refill.
 * Uses standard token bucket algorithm.
 */
fun refillTokens(bucket: TokenBucket, currentTime: Long) {
    val elapsed = currentTime - bucket.lastRefillTime
    // Calculate new tokens to add based on elapsed milliseconds
    val newTokens = (elapsed * bucket.refillRatePerMs).toInt()
    bucket.tokens = minOf(bucket.tokens + newTokens, bucket.capacity)
    bucket.lastRefillTime = currentTime
}

/**
 * Attempts to consume one token from the bucket.
 * Returns true if the request is allowed.
 */
fun tryConsume(bucket: TokenBucket): Boolean {
    if (bucket.tokens > 0) {
        bucket.tokens--
        return true
    }
    return false
}

fun checkRateLimit(clientId: String): Boolean {
    val now = System.currentTimeMillis()
    val bucket = buckets.getOrPut(clientId) {
        TokenBucket(tokens = 100, lastRefillTime = now)
    }
    synchronized(bucket) {
        refillTokens(bucket, now)
        return tryConsume(bucket)
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/transfer") {
                val clientId = getClientIdentifier(call)
                if (clientId == null) {
                    call.respond(HttpStatusCode.Unauthorized, "Invalid credentials")
                    return@post
                }

                if (!checkRateLimit(clientId)) {
                    call.respond(HttpStatusCode.TooManyRequests, "Rate limit exceeded")
                    return@post
                }

                val body = call.receiveText()
                // Process the transfer...
                call.respond(HttpStatusCode.OK, "Transfer processed for $clientId")
            }

            get("/api/health") {
                call.respond(HttpStatusCode.OK, "healthy")
            }
        }
    }.start(wait = true)
}
